#!/usr/bin/env node
/**
 * opencode-acp CLI.
 *
 * Subcommands:
 *   report   Local cost & quality X-ray from ~/.acp/opencode-local.db.
 *            No account, no network. --json for machine-readable output
 *            (agents can read their own economics), --days N for the window.
 *
 * Mirrors `hermes-acp report`. Login/provisioning is not needed for the
 * local plane — governance credentials are documented in the README.
 */
import { realpathSync } from "node:fs";
import { pathToFileURL } from "node:url";
import { PLUGIN_VERSION } from "./constants.js";
import { buildReport } from "./report.js";
const USAGE = `opencode-acp ${PLUGIN_VERSION}

Usage:
  opencode-acp report [--days N] [--json]   Local cost & quality X-ray
  opencode-acp --version                    Print version
  opencode-acp --help                       This help

The report reads ~/.acp/opencode-local.db (override: ACP_LOCAL_DB), written
locally by the opencode-acp plugin's metering plane. Nothing leaves your
machine; no account is needed. Disable metering with ACP_LOCAL_METERING=off.`;
export async function runCli(argv) {
    const args = [...argv];
    const cmd = args.shift();
    if (cmd === "--version" || cmd === "-v") {
        console.log(PLUGIN_VERSION);
        return 0;
    }
    if (cmd === undefined || cmd === "--help" || cmd === "-h" || cmd === "help") {
        console.log(USAGE);
        return cmd === undefined ? 1 : 0;
    }
    if (cmd !== "report") {
        console.error(`Unknown command: ${cmd}\n\n${USAGE}`);
        return 1;
    }
    let days = 7;
    let asJson = false;
    while (args.length) {
        const arg = args.shift();
        if (arg === "--json") {
            asJson = true;
        }
        else if (arg === "--days") {
            const v = Number(args.shift());
            if (!Number.isFinite(v) || v <= 0) {
                console.error("--days requires a positive number");
                return 1;
            }
            days = v;
        }
        else {
            console.error(`Unknown option: ${arg}\n\n${USAGE}`);
            return 1;
        }
    }
    try {
        console.log(await buildReport(days, asJson));
        return 0;
    }
    catch (err) {
        console.error(`report failed: ${String(err)}`);
        return 1;
    }
}
// Run only when invoked as a bin, not when imported (tests).
//
// npm installs a bin as a SYMLINK in node_modules/.bin (and in the global
// prefix), so when a user runs `acp-opencode` the shell hands us the symlink
// path in process.argv[1] while import.meta.url is the real file. Comparing
// the two directly means runCli() never runs through the shim: the command
// exits 0 and prints nothing. Resolve both sides through realpath first.
export function isMainEntry(argv1 = process.argv[1], moduleUrl = import.meta.url) {
    if (!argv1)
        return false;
    try {
        return moduleUrl === pathToFileURL(realpathSync(argv1)).href;
    }
    catch {
        // argv[1] may be gone or unreadable — never crash on the guard itself.
        return false;
    }
}
if (isMainEntry()) {
    runCli(process.argv.slice(2)).then((code) => process.exit(code), (err) => {
        console.error(String(err));
        process.exit(1);
    });
}

/**
 * opencode-acp — deterministic governance for OpenCode via the
 * Agentic Control Plane (https://agenticcontrolplane.com).
 *
 * Governance touchpoints (mirrors the hermes-acp contract):
 *   - permission.ask       -> POST /govern/tool-use; ACP allow => skip the native
 *                             prompt, deny => block, ask => leave "ask" so
 *                             OpenCode's native once/always/reject gate fires.
 *   - tool.execute.before  -> deny-only backstop for tools not routed through
 *                             the permission system (throw blocks the call).
 *                             Also caches args + start time by callID so
 *                             permission.ask can attach tool_input (the 1.18.4
 *                             Permission object carries no args) and the
 *                             after-hook can report duration.
 *   - tool.execute.after   -> POST /govern/tool-output (audit), awaited within
 *                             the 2 s timeout; a gateway rewrite (personal
 *                             data removed) replaces output.output when the
 *                             whole string output was sent.
 *   - chat.headers         -> stamp X-GS-Session / X-GS-Client on every LLM
 *                             request so proxy-side spend joins hook-side
 *                             audit rows (run correlation).
 *
 * FAIL-OPEN everywhere: any gateway error, timeout (2 s), or malformed
 * response lets the tool call proceed, with one loud console.warn per
 * session. ACP must never brick the harness.
 *
 * LOCAL MODE (no account, no network — see src/local.ts): active when no
 * workspace key is configured and either it's requested explicitly
 * (ACP_LOCAL=1 / plugin option `local: true`) or the installed
 * ~/.acp/decide.mjs is present. Decisions come from that on-device engine
 * instead of the gateway POSTs below; every call is appended to
 * ~/.acp/audit.jsonl. A workspace key always wins — cloud behavior is
 * unchanged when one is configured. Fail posture on an engine error mirrors
 * dsh-acp-plugin/pi-acp-plugin's attended-vs-unattended split: permission.ask
 * (a human can see the native prompt) fails OPEN, loudly; tool.execute.before
 * (deny-only backstop, no ask primitive) fails CLOSED — an unattended "ask"
 * verdict fails closed there too, for the same reason.
 *
 * LOCAL METERING (separate plane, mirrors hermes-acp 0.2.x): the `event`
 * hook records every LLM step (tokens incl. cache buckets, OpenCode's
 * in-process cost) and every tool result (status, duration) into SQLite at
 * ~/.acp/opencode-local.db. Works with ZERO credentials; nothing leaves the
 * machine. Read it back with `opencode-acp report` (--json for agents).
 * Kill switch: ACP_LOCAL_METERING=off.
 *
 * Kill switch: ACP_OPENCODE=off disables the plugin entirely.
 * Credentials: ACP_BEARER_TOKEN env var, else ~/.acp/credentials file.
 * No credentials configured => governance is a no-op (native behavior
 * stands); local metering still runs.
 */
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { CLIENT_ID, OUTPUT_REWRITE_CAPABILITY } from "./constants.js";
import { attendedFromArgv, nativeAskKeysOf, permissionKeyOf } from "./attended.js";
import { Metering } from "./metering.js";
import { cleanLine, sessionIdFromCreated } from "./text.js";
import { localAuditPost, localGovernPre, localModeActive } from "./local.js";
import { claimUnpricedNotice, providerIsAcp, rewrittenOutput, toolOutputNotice } from "./notice.js";
import { createKeyRejectionHandler, isKeyRejection, readKeyRejection } from "./key-rejected.js";
const DEFAULT_API_BASE = "https://api.agenticcontrolplane.com";
const REQUEST_TIMEOUT_MS = 2_000;
const POST_HOOK_PAYLOAD_CEILING = 200 * 1024; // 200 KB, matches backend scan ceiling
const CALL_CACHE_MAX = 1_000;
/** Resolves to `p`'s value, or null once `ms` passes or `p` rejects — a hard
 *  bound on top of the fetch abort signal, so a slow gateway can never stall
 *  an awaited hook. */
function withDeadline(p, ms) {
    return new Promise((resolve) => {
        const timer = setTimeout(() => resolve(null), ms);
        timer.unref?.();
        p.then((v) => {
            clearTimeout(timer);
            resolve(v);
        }, () => {
            clearTimeout(timer);
            resolve(null);
        });
    });
}
function apiBase() {
    return (process.env.ACP_API_BASE ?? DEFAULT_API_BASE).replace(/\/+$/, "");
}
function enabled() {
    return (process.env.ACP_OPENCODE ?? "").trim().toLowerCase() !== "off";
}
function resolveToken() {
    const env = process.env.ACP_BEARER_TOKEN;
    if (env && env.trim())
        return env.trim();
    try {
        const raw = readFileSync(join(homedir(), ".acp", "credentials"), "utf-8").trim();
        return raw || null;
    }
    catch {
        return null;
    }
}
// Fail mode when the gateway is UNREACHABLE (never a policy deny — that always
// blocks). Default OPEN: we never brick an agent the user didn't set to block.
// Opt in to blocking: ACP_FAIL_MODE=closed, or `echo closed > ~/.acp/failmode`
// (the same contract the Claude/Cursor/Codex hook + inline installer plugin use,
// so one setting covers every harness).
function failClosed() {
    const env = (process.env.ACP_FAIL_MODE ?? "").trim().toLowerCase();
    if (env === "closed")
        return true;
    if (env === "open")
        return false;
    try {
        return readFileSync(join(homedir(), ".acp", "failmode"), "utf-8").trim().toLowerCase() === "closed";
    }
    catch {
        return false;
    }
}
export const AcpPlugin = async (input, options) => {
    const localOptionEnabled = Boolean(options?.local);
    // Attended signal (tracked internally): read once from the
    // CLI subcommand (src/attended.ts). The tier follows it, so `opencode run`
    // is reported as background instead of interactive; the claim rides every
    // PreToolUse so the gateway can key native ask on it.
    const attended = attendedFromArgv();
    const tier = attended.claim ? "interactive" : "background";
    // Which tools will get OpenCode's own permission prompt after the backstop
    // lets them through: the user's resolved config routes their permission key
    // to "ask" (1.x `permission.<key>`), read once via the SDK. Unknown → none:
    // then the backstop cannot promise a prompt and must not declare native_ask.
    let nativeAskKeys;
    const asksNatively = async (tool) => {
        const key = permissionKeyOf(tool);
        if (!key || !attended.claim)
            return false;
        if (!nativeAskKeys) {
            nativeAskKeys = (async () => {
                try {
                    const get = input?.client?.config?.get;
                    return nativeAskKeysOf(get ? await get() : undefined);
                }
                catch {
                    return new Set();
                }
            })();
        }
        return (await nativeAskKeys).has(key);
    };
    /** Reason the model sees when an ask cannot be put in front of a human here. */
    const askBlockedReason = (reason) => `[ACP] Approval required (${cleanLine(reason) || "policy"}) — ${attended.claim
        ? "OpenCode's permission config does not route this tool to \"ask\", so no prompt can follow; approve it on the console Approvals page, or set the tool to \"ask\" in opencode.json"
        : `this is a headless \`opencode ${attended.mode}\` run with nobody to answer, so the call is blocked; approve it on the console Approvals page and retry`}.`;
    // Unpriced-session notice (see src/notice.ts). Sessions whose provider
    // already routes through the ACP proxy — seen on chat.headers, which fires
    // before any tool call — never get it. Bounded: cleared past 1 000 ids.
    const pricedSessions = new Set();
    // Best-effort TUI toast — the visible surface in the terminal UI. Never
    // awaited into the hook path; a failure is silence.
    const showToast = (text, variant, duration) => {
        const tui = input?.client?.tui;
        const toast = tui?.showToast;
        if (typeof toast !== "function")
            return;
        try {
            const r = toast.call(tui, { body: { title: "ACP", message: text, variant, duration } });
            r?.catch?.(() => { });
        }
        catch { /* toast is optional */ }
    };
    // Gateway notices (harness surface contract, tracked internally):
    // the same lines Claude Code prints after a call. The gateway caps them;
    // the plugin just shows what arrives.
    const relayNotice = (notice) => {
        try {
            // Client-side off switch, same contract as every other ACP plugin.
            if (/^(off|0|false)$/i.test(process.env.ACP_SHADOW ?? ""))
                return;
            const text = cleanLine(notice);
            if (text)
                showToast(text, "info", 12_000);
        }
        catch { /* never disturb a call */ }
    };
    const notifyUnpriced = (sessionID) => {
        try {
            const text = claimUnpricedNotice(sessionID, {
                pricedSession: typeof sessionID === "string" && pricedSessions.has(sessionID),
            });
            if (!text)
                return;
            console.warn(text);
            showToast(text, "warning", 15_000);
        }
        catch { /* the notice must never disturb a call */ }
    };
    // Session-start line: the daily offer and the advice tip, once per
    // session. POST /govern/session-start records nothing (this plugin has no
    // hook file to attest). Fire-and-forget.
    const startedSessions = new Set();
    const sessionStart = (sessionID, token) => {
        if (startedSessions.has(sessionID))
            return;
        if (startedSessions.size >= CALL_CACHE_MAX)
            startedSessions.clear();
        startedSessions.add(sessionID);
        void (async () => {
            try {
                const res = await fetch(`${apiBase()}/govern/session-start`, {
                    method: "POST",
                    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json", "X-GS-Client": CLIENT_ID },
                    body: JSON.stringify({ session_id: sessionID, harness: "opencode" }),
                    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
                });
                if (!res.ok)
                    return;
                const data = (await res.json().catch(() => null));
                const text = cleanLine(data?.offer, 1200);
                if (text)
                    showToast(text, "info", 20_000);
            }
            catch { /* silence */ }
        })();
    };
    // One loud warning per session (per OpenCode process), then quiet fail-open.
    let warnedThisSession = false;
    const warnOnce = (detail) => {
        if (warnedThisSession)
            return;
        warnedThisSession = true;
        const closed = failClosed();
        console.warn(`[ACP] gateway unreachable (${detail}); ` +
            (closed
                ? `failing CLOSED — tool calls are being blocked until it recovers (ACP_FAIL_MODE=closed). `
                : `failing open — tool calls proceed ungoverned. Opt in to blocking: echo closed > ~/.acp/failmode. `) +
            `Check ACP_API_BASE / network. This warning is shown once per session.`);
    };
    // Separate once-per-session warning for the LOCAL engine failing (distinct
    // trigger and message from the cloud gateway-unreachable warning above).
    let warnedLocalThisSession = false;
    const warnLocalOnce = (detail) => {
        if (warnedLocalThisSession)
            return;
        warnedLocalThisSession = true;
        console.warn(`[ACP·local] ⚠ ${detail}`);
    };
    // 401/403 is a rejected key, not an outage — its own trigger, message and
    // once-per-session flag (see src/key-rejected.ts).
    const onKeyRejected = createKeyRejectionHandler(failClosed);
    // Local mode is resolved fresh per call (mirrors resolveToken/failClosed):
    // no workspace token, and either requested explicitly or the installed
    // engine is present. See src/local.ts for the exact contract.
    const isLocalActive = (token) => localModeActive(Boolean(token), { local: localOptionEnabled });
    // Local metering state (per OpenCode process). Zero-credential plane.
    const metering = new Metering();
    // Tool-call state keyed by callID: args (for permission.ask's tool_input and
    // the audit hook), start time (duration_ms), and the governance decision
    // (so a call governed by tool.execute.before is not re-posted when
    // permission.ask fires for the same callID, and vice versa).
    const calls = new Map();
    const rememberCall = (callID, entry) => {
        if (calls.size >= CALL_CACHE_MAX) {
            const oldest = calls.keys().next().value;
            if (oldest !== undefined)
                calls.delete(oldest);
        }
        calls.set(callID, entry);
    };
    /** POST to the ACP govern endpoint. Never throws; null means fail-open;
     *  a KeyRejection means the gateway answered 401/403. `relay: false`
     *  leaves the reply's notice to the caller. */
    const govern = async (path, body, token, relay = true) => {
        try {
            const res = await fetch(`${apiBase()}${path}`, {
                method: "POST",
                headers: {
                    Authorization: `Bearer ${token}`,
                    "Content-Type": "application/json",
                    "X-GS-Client": CLIENT_ID,
                },
                body: JSON.stringify(body),
                signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
            });
            if (res.status === 401 || res.status === 403)
                return await readKeyRejection(res);
            if (!res.ok) {
                warnOnce(`HTTP ${res.status}`);
                return null;
            }
            const raw = await res.text();
            if (!raw)
                return {};
            try {
                const parsed = JSON.parse(raw);
                if (relay && parsed && typeof parsed.notice === "string")
                    relayNotice(parsed.notice);
                return parsed;
            }
            catch {
                return null; // Malformed response: fail open.
            }
        }
        catch (err) {
            warnOnce(String(err));
            return null;
        }
    };
    return {
        /**
         * LOCAL METERING — event-bus tap, no credentials required.
         * step-finish parts carry per-LLM-request token buckets + OpenCode's
         * in-process cost; terminal tool parts carry status + duration. All
         * writes are local SQLite and fail-open (see src/metering.ts).
         */
        event: async (input) => {
            try {
                if (!enabled())
                    return;
                const started = sessionIdFromCreated(input.event);
                if (started) {
                    const token = resolveToken();
                    if (token && !isLocalActive(token))
                        sessionStart(started, token);
                }
                await metering.handleEvent(input.event);
            }
            catch {
                // Metering must never disturb the session.
            }
        },
        /**
         * PRE-TOOL GOVERNANCE, primary path. Fires when OpenCode's permission
         * config routes a tool to "ask" (ship the permission block — see README).
         *   ACP allow -> output.status = "allow" (prompt skipped, pre-approved)
         *   ACP deny  -> output.status = "deny"
         *   ACP ask   -> leave "ask" (OpenCode's native once/always/reject gate)
         *
         * ATTENDED hook: a human can see the native permission gate, so an engine
         * failure here fails OPEN (loudly) — the same posture as a cloud gateway
         * outage.
         */
        "permission.ask": async (input, output) => {
            try {
                if (!enabled())
                    return;
                const token = resolveToken();
                const local = isLocalActive(token);
                if (!token && !local)
                    return;
                const callID = input.callID;
                const cached = callID ? calls.get(callID) : undefined;
                if (local) {
                    let decision = cached?.decision;
                    if (!decision) {
                        const result = await localGovernPre(input.type, cached?.args ?? input.metadata ?? {});
                        if (result.outcome === "engine-error") {
                            warnLocalOnce("decision engine unavailable — this call ran UNGOVERNED and was allowed " +
                                "(attended fail-open). Re-run the installer to restore ~/.acp/decide.mjs.");
                            return; // fail OPEN: leave output.status untouched.
                        }
                        decision = result.decision;
                        if (cached)
                            cached.decision = decision;
                    }
                    if (decision.decision === "allow")
                        output.status = "allow";
                    else if (decision.decision === "deny")
                        output.status = "deny";
                    // "ask": leave output.status untouched (native gate fires), same as
                    // cloud — unless nobody is at a TUI: `opencode run` answers its own
                    // prompts, so an ask left standing would run.
                    else if (decision.decision === "ask" && !attended.claim)
                        output.status = "deny";
                    return;
                }
                if (!token)
                    return;
                let result = cached?.decision;
                if (!result) {
                    const answer = (await govern("/govern/tool-use", {
                        // Permission.type is the tool name on 1.18.4 (verified against
                        // @opencode-ai/sdk types: id, type, pattern?, sessionID,
                        // messageID, callID?, title, metadata, time — no args field).
                        tool_name: input.type,
                        tool_input: cached?.args ?? input.metadata ?? {},
                        session_id: input.sessionID,
                        hook_event_name: "PreToolUse",
                        agent_tier: tier,
                        attended,
                        // This hook IS the prompt: leaving status "ask" renders
                        // OpenCode's own once/always/reject gate — when a human is
                        // there to answer it.
                        capabilities: attended.claim ? ["native_ask"] : [],
                    }, token)) ?? undefined;
                    if (isKeyRejection(answer)) {
                        // Rejected key: never cached, so a fixed key takes effect next call.
                        if (onKeyRejected(answer, input.type, input.sessionID))
                            output.status = "deny";
                        return;
                    }
                    result = answer;
                    if (result && cached)
                        cached.decision = result;
                }
                if (!result) {
                    // Infra failure (token was present). Fail-closed blocks the call;
                    // fail-open (default) leaves the native gate to stand.
                    if (failClosed())
                        output.status = "deny";
                    return;
                }
                if (result.decision === "allow") {
                    output.status = "allow";
                    notifyUnpriced(input.sessionID); // allow path only, once per session
                }
                else if (result.decision === "deny")
                    output.status = "deny";
                else if (result.decision === "ask") {
                    if (!attended.claim) {
                        // Headless: OpenCode would answer its own prompt. Deny + console.
                        output.status = "deny";
                        warnOnce(askBlockedReason(result.reason));
                    }
                    else {
                        // Leave status "ask": the native gate renders. OpenCode's prompt
                        // carries its own title, so the gateway's reason goes up as a
                        // toast beside it.
                        const text = cleanLine(result.reason);
                        if (text)
                            showToast(text, "warning", 20_000);
                    }
                }
                // Anything else: leave output.status untouched.
            }
            catch (err) {
                warnOnce(String(err)); // Never brick the permission flow.
            }
        },
        /**
         * DENY-ONLY BACKSTOP for tools not routed through the permission system.
         * The only block primitive here is `throw`; the message surfaces to the
         * model, so it carries the policy reason.
         *
         * UNATTENDED hook: there is no human-visible prompt at this point (no ask
         * primitive exists here), so both an engine failure AND a local "ask"
         * verdict fail CLOSED — the mirror image of permission.ask's attended
         * fail-open, and the same posture dsh-acp-plugin/pi-acp-plugin use for
         * their unattended tiers.
         */
        "tool.execute.before": async (input, output) => {
            let denyError = null;
            try {
                if (!enabled())
                    return;
                const entry = { args: output.args, startMs: Date.now() };
                rememberCall(input.callID, entry);
                const token = resolveToken();
                const local = isLocalActive(token);
                if (!token && !local)
                    return;
                if (local) {
                    const result = await localGovernPre(input.tool, output.args);
                    if (result.outcome === "engine-error") {
                        denyError = new Error("[ACP·local] decision engine unavailable — blocked (fail-closed, unattended). " +
                            "Re-run the installer to restore ~/.acp/decide.mjs.");
                    }
                    else {
                        entry.decision = result.decision;
                        if (result.decision.decision === "deny") {
                            denyError = new Error(`[ACP·local] Denied by policy: ${result.decision.reason}`);
                        }
                        else if (result.decision.decision === "ask") {
                            denyError = new Error(`[ACP·local] Requires approval (${result.decision.reason}) — no approval surface ` +
                                "at this hook, failing closed (unattended).");
                        }
                    }
                }
                else if (token) {
                    // native_ask here is a promise that permission.ask will fire next for
                    // this call and render the prompt: only when the user's config routes
                    // the tool to "ask" and a human is at the TUI.
                    const promptFollows = await asksNatively(input.tool);
                    const result = await govern("/govern/tool-use", {
                        tool_name: input.tool,
                        tool_input: output.args,
                        session_id: input.sessionID,
                        hook_event_name: "PreToolUse",
                        agent_tier: tier,
                        attended,
                        capabilities: promptFollows ? ["native_ask"] : [],
                    }, token);
                    if (isKeyRejection(result)) {
                        const block = onKeyRejected(result, input.tool, input.sessionID);
                        if (block)
                            denyError = new Error(block);
                    }
                    else if (!result) {
                        // Infra failure (token was present). Set denyError (thrown after the
                        // try) only when fail-closed — throwing inside the try would be
                        // swallowed by the catch below and silently fail open.
                        if (failClosed()) {
                            denyError = new Error(`[ACP] gateway unreachable — blocked (fail-closed). Set ACP_FAIL_MODE=open or remove ~/.acp/failmode to allow.`);
                        }
                    }
                    else {
                        entry.decision = result;
                        if (result.decision === "deny") {
                            denyError = new Error(`[ACP] Denied by policy: ${result.reason ?? "policy did not return a reason"}`);
                        }
                        else if (result.decision === "allow") {
                            notifyUnpriced(input.sessionID); // allow path only, once per session
                        }
                        else if (result.decision === "ask" && !promptFollows) {
                            // No prompt can follow this hook for this call, so an "ask" that
                            // fell through here would run unanswered. Fail closed with the
                            // console route (never ask → allow).
                            denyError = new Error(askBlockedReason(result.reason));
                        }
                        // "ask" with promptFollows: cached; permission.ask renders it next.
                    }
                }
            }
            catch (err) {
                warnOnce(String(err)); // Fail-open on anything unexpected (a bug, not the gateway).
            }
            if (denyError)
                throw denyError;
        },
        /**
         * POST-TOOL AUDIT + PERSONAL DATA REMOVAL. The reply is awaited, bounded
         * by the 2 s request timeout, because OpenCode hands `output.output` to
         * the model after this hook: a gateway rewrite replaces it. The rewrite
         * capability is declared only when the whole string output was sent, and
         * a rewrite is applied only when declared. Any failure leaves the
         * original output. Local mode only records the call
         * (~/.acp/audit.jsonl); there is no on-device equivalent of the cloud
         * path's DLP/redact scan.
         */
        "tool.execute.after": async (input, output) => {
            try {
                const entry = calls.get(input.callID);
                calls.delete(input.callID);
                if (!enabled())
                    return;
                const token = resolveToken();
                if (isLocalActive(token)) {
                    localAuditPost(input.tool);
                    return;
                }
                if (!token)
                    return;
                const original = output.output;
                let out = typeof original === "string" ? original : String(original ?? "");
                let truncated = false;
                if (Buffer.byteLength(out, "utf-8") > POST_HOOK_PAYLOAD_CEILING) {
                    out = out.slice(0, POST_HOOK_PAYLOAD_CEILING);
                    truncated = true;
                }
                const declared = typeof original === "string" && !truncated;
                const reply = await withDeadline(govern("/govern/tool-output", {
                    tool_name: input.tool,
                    tool_input: input.args,
                    tool_output: out,
                    session_id: input.sessionID,
                    duration_ms: entry ? Date.now() - entry.startMs : 0,
                    hook_event_name: "PostToolUse",
                    agent_tier: tier,
                    ...(declared ? { capabilities: [OUTPUT_REWRITE_CAPABILITY] } : {}),
                }, token, false), REQUEST_TIMEOUT_MS);
                if (!reply || isKeyRejection(reply))
                    return; // fail open: original output stands
                let replaced = false;
                const rewritten = declared ? rewrittenOutput(reply, out) : null;
                if (rewritten !== null && rewritten !== original) {
                    output.output = rewritten;
                    replaced = true;
                }
                relayNotice(toolOutputNotice(reply, replaced));
            }
            catch {
                // Best-effort; never disturb the tool result.
            }
        },
        /**
         * RUN CORRELATION — stamp session identity onto every LLM request so
         * proxy-side spend joins hook-side audit rows.
         */
        "chat.headers": async (input, output) => {
            try {
                if (!enabled())
                    return;
                output.headers["X-GS-Session"] = input.sessionID;
                output.headers["X-GS-Client"] = CLIENT_ID;
                // This session's model calls go through the ACP proxy: it is priced,
                // whatever the launcher env says (e.g. acp/<model> picked by hand).
                if (providerIsAcp(input.provider, input.model)) {
                    if (pricedSessions.size >= CALL_CACHE_MAX)
                        pricedSessions.clear();
                    pricedSessions.add(input.sessionID);
                }
            }
            catch {
                // Never disturb the request.
            }
        },
    };
};
// Note: no default export — OpenCode's loader invokes every exported plugin
// function; a default alias of AcpPlugin would register the hooks twice.
